export type BookStatus = "reading" | "finished";

export interface Book {
  id: string;
  title: string;
  author: string;
  status: BookStatus;
  notes: string;
  createdAt: string;
  finishedAt?: string | null;
}

export interface CreateBookInput {
  title: string;
  author: string;
  notes?: string;
  status?: BookStatus;
}

export interface UpdateBookInput {
  title?: string;
  author?: string;
  notes?: string;
  status?: BookStatus;
}

import fs from "node:fs/promises";
import path from "node:path";
import crypto from "node:crypto";
import { Book, CreateBookInput, UpdateBookInput } from "./types";

const DATA_DIR = path.join(process.cwd(), "data");
const DATA_FILE = path.join(DATA_DIR, "books.json");

const INITIAL_BOOKS: Book[] = [
  {
    id: "tomorrow-and-tomorrow",
    title: "Tomorrow, and Tomorrow, and Tomorrow",
    author: "Gabrielle Zevin",
    status: "reading",
    notes: "A breathtaking novel about creative partnership, identity, and play. The world-building and character dynamics between Sam and Sadie are unforgettable.",
    createdAt: new Date(Date.now() - 5 * 24 * 60 * 60 * 1000).toISOString(),
    finishedAt: null,
  },
  {
    id: "klara-and-the-sun",
    title: "Klara and the Sun",
    author: "Kazuo Ishiguro",
    status: "finished",
    notes: "A poignant exploration of devotion, artificial intelligence, and what makes human connection so fragile yet enduring.",
    createdAt: new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString(),
    finishedAt: new Date(Date.now() - 10 * 24 * 60 * 60 * 1000).toISOString(),
  },
];

async function ensureDataFile(): Promise<void> {
  try {
    await fs.mkdir(DATA_DIR, { recursive: true });
    try {
      await fs.access(DATA_FILE);
    } catch {
      await fs.writeFile(
        DATA_FILE,
        JSON.stringify(INITIAL_BOOKS, null, 2),
        "utf-8"
      );
    }
  } catch (error) {
    console.error("Failed to ensure data file:", error);
  }
}

export async function getBooks(): Promise<Book[]> {
  await ensureDataFile();
  try {
    const content = await fs.readFile(DATA_FILE, "utf-8");
    const books: Book[] = JSON.parse(content);
    return books;
  } catch (error) {
    console.error("Failed to read books:", error);
    return [];
  }
}

export async function getBookById(id: string): Promise<Book | null> {
  const books = await getBooks();
  return books.find((book) => book.id === id) || null;
}

export async function saveBooks(books: Book[]): Promise<void> {
  await ensureDataFile();
  const tempFile = `${DATA_FILE}.tmp`;
  await fs.writeFile(tempFile, JSON.stringify(books, null, 2), "utf-8");
  await fs.rename(tempFile, DATA_FILE);
}

export async function createBook(input: CreateBookInput): Promise<Book> {
  const books = await getBooks();
  const id = crypto.randomUUID().slice(0, 8);
  const now = new Date().toISOString();
  const isFinished = input.status === "finished";

  const newBook: Book = {
    id,
    title: input.title.trim(),
    author: input.author.trim(),
    notes: input.notes?.trim() || "",
    status: input.status || "reading",
    createdAt: now,
    finishedAt: isFinished ? now : null,
  };

  books.unshift(newBook);
  await saveBooks(books);
  return newBook;
}

export async function updateBook(
  id: string,
  input: UpdateBookInput
): Promise<Book | null> {
  const books = await getBooks();
  const index = books.findIndex((book) => book.id === id);
  if (index === -1) {
    return null;
  }

  const currentBook = books[index];
  const nextStatus = input.status ?? currentBook.status;
  let finishedAt = currentBook.finishedAt;

  if (nextStatus === "finished" && currentBook.status !== "finished") {
    finishedAt = new Date().toISOString();
  } else if (nextStatus === "reading" && currentBook.status === "finished") {
    finishedAt = null;
  }

  const updatedBook: Book = {
    ...currentBook,
    ...(input.title !== undefined && { title: input.title.trim() }),
    ...(input.author !== undefined && { author: input.author.trim() }),
    ...(input.notes !== undefined && { notes: input.notes.trim() }),
    status: nextStatus,
    finishedAt,
  };

  books[index] = updatedBook;
  await saveBooks(books);
  return updatedBook;
}

export async function markBookAsFinished(id: string): Promise<Book | null> {
  return updateBook(id, { status: "finished" });
}

export async function deleteBook(id: string): Promise<boolean> {
  const books = await getBooks();
  const filtered = books.filter((b) => b.id !== id);
  if (filtered.length === books.length) {
    return false;
  }
  await saveBooks(filtered);
  return true;
}

