"use client";

import { useState } from "react";
import { Book } from "@/lib/types";
import { PlusCircle, Loader2, BookPlus } from "lucide-react";

interface AddBookFormProps {
  onBookAdded: (newBook: Book) => void;
}

export default function AddBookForm({ onBookAdded }: AddBookFormProps) {
  const [isOpen, setIsOpen] = useState(false);
  const [title, setTitle] = useState("");
  const [author, setAuthor] = useState("");
  const [status, setStatus] = useState<"reading" | "finished">("reading");
  const [notes, setNotes] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (!title.trim() || !author.trim()) {
      setError("Please provide both title and author.");
      return;
    }

    setIsSubmitting(true);
    setError(null);

    try {
      const res = await fetch("/api/books", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          title: title.trim(),
          author: author.trim(),
          status,
          notes: notes.trim(),
        }),
      });

      if (!res.ok) {
        const data = await res.json();
        throw new Error(data.error || "Failed to add book");
      }

      const createdBook: Book = await res.json();
      onBookAdded(createdBook);

      // Reset form
      setTitle("");
      setAuthor("");
      setNotes("");
      setStatus("reading");
      setIsOpen(false);
    } catch (err: any) {
      setError(err.message || "Something went wrong. Please try again.");
    } finally {
      setIsSubmitting(false);
    }
  }

  return (
    <div className="bg-white rounded-2xl border border-stone-200/90 shadow-sm overflow-hidden mb-8 transition-all">
      {!isOpen ? (
        <button
          onClick={() => setIsOpen(true)}
          className="w-full px-6 py-4 flex items-center justify-between text-left hover:bg-stone-50/80 transition-colors group"
        >
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 rounded-full bg-amber-50 border border-amber-200 flex items-center justify-center text-amber-800 group-hover:scale-105 transition-transform">
              <PlusCircle className="w-4 h-4" />
            </div>
            <div>
              <span className="font-medium text-stone-900 group-hover:text-amber-900 transition-colors">
                Add a new book
              </span>
              <p className="text-xs text-stone-700">
                Log a book you are reading or have finished
              </p>
            </div>
          </div>
          <span className="text-xs font-semibold px-2.5 py-1 rounded-full bg-stone-100 text-stone-600 group-hover:bg-amber-100 group-hover:text-amber-900 transition-colors">
            + New Entry
          </span>
        </button>
      ) : (
        <form onSubmit={handleSubmit} className="p-6">
          <div className="flex items-center justify-between pb-4 border-b border-stone-100 mb-5">
            <div className="flex items-center gap-2 text-stone-900 font-serif font-semibold text-lg">
              <BookPlus className="w-5 h-5 text-amber-800" />
              <span>Add Book to Library</span>
            </div>
            <button
              type="button"
              onClick={() => {
                setIsOpen(false);
                setError(null);
              }}
              className="text-stone-700 hover:text-stone-900 text-sm font-medium transition-colors"
            >
              Cancel
            </button>
          </div>

          {error && (
            <div className="mb-4 p-3 rounded-lg bg-red-50 border border-red-200 text-red-700 text-sm">
              {error}
            </div>
          )}

          <div className="space-y-4">
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div>
                <label
                  htmlFor="title"
                  className="block text-xs font-semibold uppercase tracking-wider text-stone-700 mb-1.5"
                >
                  Book Title *
                </label>
                <input
                  id="title"
                  type="text"
                  required
                  value={title}
                  onChange={(e) => setTitle(e.target.value)}
                  placeholder="e.g. The Great Gatsby"
                  className="w-full px-3.5 py-2 rounded-lg border border-stone-300 bg-stone-50/50 text-stone-900 placeholder:text-stone-400 focus:outline-none focus:ring-2 focus:ring-amber-800/20 focus:border-amber-800 transition-all text-sm"
                />
              </div>

              <div>
                <label
                  htmlFor="author"
                  className="block text-xs font-semibold uppercase tracking-wider text-stone-700 mb-1.5"
                >
                  Author *
                </label>
                <input
                  id="author"
                  type="text"
                  required
                  value={author}
                  onChange={(e) => setAuthor(e.target.value)}
                  placeholder="e.g. F. Scott Fitzgerald"
                  className="w-full px-3.5 py-2 rounded-lg border border-stone-300 bg-stone-50/50 text-stone-900 placeholder:text-stone-400 focus:outline-none focus:ring-2 focus:ring-amber-800/20 focus:border-amber-800 transition-all text-sm"
                />
              </div>
            </div>

            <div>
              <label className="block text-xs font-semibold uppercase tracking-wider text-stone-700 mb-1.5">
                Current Status
              </label>
              <div className="flex gap-3">
                <label
                  className={`flex-1 flex items-center justify-center gap-2 p-2.5 rounded-lg border text-sm font-medium cursor-pointer transition-all ${
                    status === "reading"
                      ? "border-amber-700 bg-amber-50/70 text-amber-900 font-semibold shadow-xs"
                      : "border-stone-200 bg-white text-stone-600 hover:bg-stone-50"
                  }`}
                >
                  <input
                    type="radio"
                    name="status"
                    value="reading"
                    checked={status === "reading"}
                    onChange={() => setStatus("reading")}
                    className="sr-only"
                  />
                  <span>Currently Reading</span>
                </label>

                <label
                  className={`flex-1 flex items-center justify-center gap-2 p-2.5 rounded-lg border text-sm font-medium cursor-pointer transition-all ${
                    status === "finished"
                      ? "border-emerald-700 bg-emerald-50/70 text-emerald-900 font-semibold shadow-xs"
                      : "border-stone-200 bg-white text-stone-600 hover:bg-stone-50"
                  }`}
                >
                  <input
                    type="radio"
                    name="status"
                    value="finished"
                    checked={status === "finished"}
                    onChange={() => setStatus("finished")}
                    className="sr-only"
                  />
                  <span>Finished</span>
                </label>
              </div>
            </div>

            <div>
              <label
                htmlFor="notes"
                className="block text-xs font-semibold uppercase tracking-wider text-stone-700 mb-1.5"
              >
                Notes & Reflections{" "}
                <span className="text-stone-700 font-normal lowercase">
                  (optional)
                </span>
              </label>
              <textarea
                id="notes"
                rows={3}
                value={notes}
                onChange={(e) => setNotes(e.target.value)}
                placeholder="Memorable quotes, key takeaways, favorite characters, or personal thoughts..."
                className="w-full px-3.5 py-2.5 rounded-lg border border-stone-300 bg-stone-50/50 text-stone-900 placeholder:text-stone-400 focus:outline-none focus:ring-2 focus:ring-amber-800/20 focus:border-amber-800 transition-all text-sm resize-y"
              />
            </div>
          </div>

          <div className="mt-5 flex items-center justify-end gap-3 pt-3 border-t border-stone-100">
            <button
              type="button"
              onClick={() => setIsOpen(false)}
              className="px-4 py-2 text-sm font-medium text-stone-600 hover:text-stone-800 transition-colors"
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={isSubmitting}
              className="inline-flex items-center gap-2 px-5 py-2 rounded-lg bg-amber-900 hover:bg-amber-800 active:bg-amber-950 text-amber-50 font-medium text-sm transition-colors shadow-sm disabled:opacity-50"
            >
              {isSubmitting && <Loader2 className="w-4 h-4 animate-spin" />}
              <span>Save Book</span>
            </button>
          </div>
        </form>
      )}
    </div>
  );
}

