  onUpdateStatus: (id: string, newStatus: BookStatus) => Promise<void>;
}

export default function BookCard({ book, onUpdateStatus }: BookCardProps) {
  const [isUpdating, setIsUpdating] = useState(false);
  const [copied, setCopied] = useState(false);

  async function handleToggleStatus(e: React.MouseEvent) {
    e.preventDefault();
    e.stopPropagation();
    setIsUpdating(true);
    const nextStatus: BookStatus = book.status === "reading" ? "finished" : "reading";
    try {
      await onUpdateStatus(book.id, nextStatus);
    } finally {
      setIsUpdating(false);
    }
  }

  function handleShare(e: React.MouseEvent) {
    e.preventDefault();
    e.stopPropagation();
    const url = `${window.location.origin}/books/${book.id}`;
    navigator.clipboard.writeText(url);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  }

  const isReading = book.status === "reading";

  return (
    <div className="group relative bg-white rounded-xl border border-stone-200/90 hover:border-amber-900/30 shadow-xs hover:shadow-md transition-all duration-200 flex flex-col justify-between p-5">
      <div>
        <div className="flex items-start justify-between gap-3 mb-2.5">
          <span
            className={`inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-full text-xs font-medium tracking-wide ${
              isReading
                ? "bg-amber-100/80 text-amber-900 border border-amber-200/60"
                : "bg-emerald-100/80 text-emerald-900 border border-emerald-200/60"
            }`}
          >
            <span
              className={`w-1.5 h-1.5 rounded-full ${
                isReading ? "bg-amber-600 animate-pulse" : "bg-emerald-600"
              }`}
            />
            {isReading ? "Reading" : "Finished"}
          </span>

          <button
            onClick={handleShare}
            title="Copy shareable link to book"
            className="text-stone-700 hover:text-stone-900 p-1 rounded-md hover:bg-stone-100 transition-colors"
          >
            {copied ? (
              <span className="text-[11px] text-emerald-600 font-medium flex items-center gap-1">
                <Check className="w-3.5 h-3.5" /> Copied
              </span>
            ) : (
              <Share2 className="w-3.5 h-3.5" />
            )}
          </button>
        </div>

        <Link href={`/books/${book.id}`} className="block group-hover:text-amber-900 transition-colors">
          <h3 className="font-serif text-lg font-bold text-stone-900 tracking-tight leading-snug group-hover:text-amber-900 transition-colors">
            {book.title}
          </h3>
          <p className="text-sm text-stone-700 mt-0.5 font-medium">by {book.author}</p>
        </Link>

        {book.notes ? (
          <p className="mt-3 text-xs text-stone-700 line-clamp-3 leading-relaxed bg-stone-50/60 p-2.5 rounded-lg border border-stone-100 font-normal">
            &ldquo;{book.notes}&rdquo;
          </p>
        ) : (
          <p className="mt-3 text-xs text-stone-700 italic">No notes added yet</p>
        )}
      </div>

      <div className="mt-5 pt-3 border-t border-stone-100 flex items-center justify-between gap-2">
        <button
          onClick={handleToggleStatus}
          disabled={isUpdating}
          className={`inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-semibold transition-all disabled:opacity-50 ${
            isReading
              ? "bg-stone-100 hover:bg-emerald-50 text-stone-700 hover:text-emerald-800 border border-stone-200 hover:border-emerald-200"
              : "bg-stone-50 hover:bg-amber-50 text-stone-700 hover:text-amber-800 border border-stone-200 hover:border-amber-200"
          }`}
        >
          {isUpdating ? (
            <Loader2 className="w-3.5 h-3.5 animate-spin" />
          ) : isReading ? (
            <CheckCircle2 className="w-3.5 h-3.5 text-emerald-600" />
          ) : (
            <RotateCcw className="w-3.5 h-3.5 text-amber-600" />
          )}
          <span>{isReading ? "Mark Finished" : "Re-read"}</span>
        </button>

        <Link
          href={`/books/${book.id}`}
          className="inline-flex items-center gap-1 text-xs font-semibold text-amber-900 hover:text-amber-700 hover:underline transition-colors"
        >
          <span>Notes & Details</span>
          <ArrowRight className="w-3 h-3 group-hover:translate-x-0.5 transition-transform" />
        </Link>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { Book, BookStatus } from "@/lib/types";
import AddBookForm from "@/components/AddBookForm";
import BookCard from "@/components/BookCard";
import { BookOpen, CheckCircle, Sparkles, Library } from "lucide-react";

export default function HomePage() {
  const [books, setBooks] = useState<Book[]>([]);
  const [loading, setLoading] = useState(true);

  async function fetchBooks() {
    try {
      const res = await fetch("/api/books");
      if (res.ok) {
        const data = await res.json();
        setBooks(data);
      }
    } catch (err) {
      console.error("Failed to load books:", err);
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    fetchBooks();
  }, []);

  function handleBookAdded(newBook: Book) {
    setBooks((prev) => [newBook, ...prev]);
  }

  async function handleUpdateStatus(id: string, newStatus: BookStatus) {
    // Optimistic UI update
    setBooks((prev) =>
      prev.map((b) =>
        b.id === id
          ? {
              ...b,
              status: newStatus,
              finishedAt:
                newStatus === "finished" ? new Date().toISOString() : null,
            }
          : b
      )
    );

    try {
      const res = await fetch(`/api/books/${id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status: newStatus }),
      });
      if (!res.ok) {
        // Revert on error
        await fetchBooks();
      }
    } catch (err) {
      console.error("Failed to update status:", err);
      await fetchBooks();
    }
  }

  const currentlyReading = books.filter((b) => b.status === "reading");
  const finished = books.filter((b) => b.status === "finished");

  return (
    <div className="space-y-10">
      {/* Intro hero & stats */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 pb-2 border-b border-stone-200/80">
        <div>
          <h1 className="font-serif text-3xl sm:text-4xl font-bold tracking-tight text-stone-900">
            My Reading Shelf
          </h1>
          <p className="text-stone-700 text-sm mt-1">
            Keep track of what you&apos;re reading, what you&apos;ve completed,
            and your personal reflections.
          </p>
        </div>

        <div className="flex items-center gap-3 self-start sm:self-auto">
          <div className="flex items-center gap-2 px-3 py-1.5 rounded-lg bg-amber-50 border border-amber-200 text-amber-900 text-xs font-semibold">
            <BookOpen className="w-3.5 h-3.5 text-amber-700" />
            <span>{currentlyReading.length} Reading</span>
          </div>
          <div className="flex items-center gap-2 px-3 py-1.5 rounded-lg bg-emerald-50 border border-emerald-200 text-emerald-900 text-xs font-semibold">
            <CheckCircle className="w-3.5 h-3.5 text-emerald-700" />
            <span>{finished.length} Finished</span>
          </div>
        </div>
      </div>

      {/* Add Book Form Component */}
      <AddBookForm onBookAdded={handleBookAdded} />

      {loading ? (
        <div className="text-center py-16 text-stone-700 space-y-3">
          <div className="inline-block w-6 h-6 border-2 border-amber-800 border-t-transparent rounded-full animate-spin" />
          <p className="text-sm">Loading your reading log...</p>
        </div>
      ) : (
        <div className="space-y-12">
          {/* Currently Reading Section */}
          <section aria-labelledby="currently-reading-heading">
            <div className="flex items-center justify-between mb-4">
              <div className="flex items-center gap-2.5">
                <div className="w-2.5 h-2.5 rounded-full bg-amber-500 animate-pulse" />
                <h2
                  id="currently-reading-heading"
                  className="font-serif text-2xl font-bold tracking-tight text-stone-900"
                >
                  Currently Reading
                </h2>
                <span className="text-xs font-semibold px-2 py-0.5 rounded-full bg-amber-100/80 text-amber-900 border border-amber-200">
                  {currentlyReading.length}
                </span>
              </div>
            </div>

            {currentlyReading.length === 0 ? (
              <div className="rounded-xl border border-dashed border-stone-300 p-8 text-center bg-stone-50/50">
                <Sparkles className="w-8 h-8 mx-auto text-amber-700/60 mb-2" />
                <p className="text-sm font-medium text-stone-700">
                  You aren&apos;t currently reading any books.
                </p>
                <p className="text-xs text-stone-700 mt-1">
                  Add one using the form above to start tracking!
                </p>
              </div>
            ) : (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {currentlyReading.map((book) => (
                  <BookCard
                    key={book.id}
                    book={book}
                    onUpdateStatus={handleUpdateStatus}
                  />
                ))}
              </div>
            )}
          </section>

          {/* Finished Section */}
          <section aria-labelledby="finished-heading">
            <div className="flex items-center justify-between mb-4">
              <div className="flex items-center gap-2.5">
                <div className="w-2.5 h-2.5 rounded-full bg-emerald-600" />
                <h2
                  id="finished-heading"
                  className="font-serif text-2xl font-bold tracking-tight text-stone-900"
                >
                  Finished
                </h2>
                <span className="text-xs font-semibold px-2 py-0.5 rounded-full bg-emerald-100/80 text-emerald-900 border border-emerald-200">
                  {finished.length}
                </span>
              </div>
            </div>

            {finished.length === 0 ? (
              <div className="rounded-xl border border-dashed border-stone-300 p-8 text-center bg-stone-50/50">
                <Library className="w-8 h-8 mx-auto text-stone-400 mb-2" />
                <p className="text-sm font-medium text-stone-700">
                  No finished books yet.
                </p>
                <p className="text-xs text-stone-700 mt-1">
                  When you finish a book, mark it as finished and it will appear here.
                </p>
              </div>
            ) : (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {finished.map((book) => (
                  <BookCard
                    key={book.id}
                    book={book}
                    onUpdateStatus={handleUpdateStatus}
                  />
                ))}
              </div>
            )}
          </section>
        </div>
      )}
    </div>
  );
}

