"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { Book, BookStatus } from "@/lib/types";
import {
  Share2,
  Check,
  CheckCircle2,
  RotateCcw,
  Edit3,
  Loader2,
  Trash2,
  ExternalLink,
} from "lucide-react";

interface BookDetailActionsProps {
  initialBook: Book;
}

export default function BookDetailActions({
  initialBook,
}: BookDetailActionsProps) {
  const router = useRouter();
  const [book, setBook] = useState<Book>(initialBook);
  const [copied, setCopied] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editedNotes, setEditedNotes] = useState(book.notes);
  const [isSaving, setIsSaving] = useState(false);
  const [isUpdatingStatus, setIsUpdatingStatus] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  function copyLink() {
    const url = window.location.href;
    navigator.clipboard.writeText(url);
    setCopied(true);
    setTimeout(() => setCopied(false), 2500);
  }

  async function handleToggleStatus() {
    setIsUpdatingStatus(true);
    const nextStatus: BookStatus =
      book.status === "reading" ? "finished" : "reading";

    try {
      const res = await fetch(`/api/books/${book.id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status: nextStatus }),
      });

      if (res.ok) {
        const updated = await res.json();
        setBook(updated);
        router.refresh();
      }
    } catch (err) {
      console.error("Failed to toggle status:", err);
    } finally {
      setIsUpdatingStatus(false);
    }
  }

  async function handleSaveNotes() {
    setIsSaving(true);
    try {
      const res = await fetch(`/api/books/${book.id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ notes: editedNotes }),
      });

      if (res.ok) {
        const updated = await res.json();
        setBook(updated);
        setIsEditing(false);
        router.refresh();
      }
    } catch (err) {
      console.error("Failed to save notes:", err);
    } finally {
      setIsSaving(false);
    }
  }

  async function handleDelete() {
    if (
      !window.confirm(
        `Are you sure you want to remove "${book.title}" from your library?`
      )
    ) {
      return;
    }

    setIsDeleting(true);
    try {
      const res = await fetch(`/api/books/${book.id}`, {
        method: "DELETE",
      });

      if (res.ok) {
        router.push("/");
        router.refresh();
      }
    } catch (err) {
      console.error("Failed to delete book:", err);
      setIsDeleting(false);
    }
  }

  const isReading = book.status === "reading";

  return (
    <div className="space-y-6">
      {/* Action toolbar */}
      <div className="flex flex-wrap items-center justify-between gap-3 p-4 rounded-xl bg-stone-100/70 border border-stone-200">
        <div className="flex flex-wrap items-center gap-2">
          {/* Status Toggle Button */}
          <button
            onClick={handleToggleStatus}
            disabled={isUpdatingStatus}
            className={`inline-flex items-center gap-1.5 px-3.5 py-2 rounded-lg text-xs font-semibold shadow-xs transition-all disabled:opacity-50 ${
              isReading
                ? "bg-emerald-700 hover:bg-emerald-800 text-white"
                : "bg-amber-800 hover:bg-amber-900 text-amber-50"
            }`}
          >
            {isUpdatingStatus ? (
              <Loader2 className="w-4 h-4 animate-spin" />
            ) : isReading ? (
              <CheckCircle2 className="w-4 h-4" />
            ) : (
              <RotateCcw className="w-4 h-4" />
            )}
            <span>
              {isReading ? "Mark as Finished" : "Mark as Currently Reading"}
            </span>
          </button>

          {/* Edit Notes Button */}
          <button
            onClick={() => {
              setEditedNotes(book.notes);
              setIsEditing(!isEditing);
            }}
            className="inline-flex items-center gap-1.5 px-3.5 py-2 rounded-lg text-xs font-medium bg-white hover:bg-stone-50 text-stone-700 border border-stone-300 transition-colors shadow-xs"
          >
            <Edit3 className="w-3.5 h-3.5 text-stone-700" />
            <span>{isEditing ? "Close Notes Editor" : "Edit Notes"}</span>
          </button>
        </div>

        <div className="flex items-center gap-2">
          {/* Share Button */}
          <button
            onClick={copyLink}
            className="inline-flex items-center gap-1.5 px-3.5 py-2 rounded-lg text-xs font-medium bg-white hover:bg-stone-50 text-stone-800 border border-stone-300 transition-colors shadow-xs"
          >
            {copied ? (
              <>
                <Check className="w-3.5 h-3.5 text-emerald-600" />
                <span className="text-emerald-700 font-semibold">
                  Link Copied!
                </span>
              </>
            ) : (
              <>
                <Share2 className="w-3.5 h-3.5 text-stone-700" />
                <span>Share Book Link</span>
              </>
            )}
          </button>

          {/* Delete Button */}
          <button
            onClick={handleDelete}
            disabled={isDeleting}
            title="Remove book from reading log"
            className="p-2 rounded-lg text-stone-700 hover:text-red-600 hover:bg-red-50 transition-colors"
          >
            {isDeleting ? (
              <Loader2 className="w-4 h-4 animate-spin" />
            ) : (
              <Trash2 className="w-4 h-4" />
            )}
          </button>
        </div>
      </div>

      {/* Shareable Link Box */}
      {copied && (
        <div className="p-3 bg-emerald-50 border border-emerald-200 rounded-lg text-xs text-emerald-800 flex items-center justify-between animate-fadeIn">
          <div className="flex items-center gap-2">
            <CheckCircle2 className="w-4 h-4 text-emerald-600 shrink-0" />
            <span>
              Shareable link copied to your clipboard. Anyone with this link can
              view this book!
            </span>
          </div>
        </div>
      )}

      {/* Inline Notes Editor */}
      {isEditing && (
        <div className="p-5 bg-amber-50/50 rounded-xl border border-amber-200/80 space-y-3">
          <h4 className="text-xs font-semibold uppercase tracking-wider text-amber-900">
            Edit Your Notes & Reflections
          </h4>
          <textarea
            rows={5}
            value={editedNotes}
            onChange={(e) => setEditedNotes(e.target.value)}
            placeholder="Add your reflections, review, quotes, or thoughts on this book..."
            className="w-full px-3.5 py-2.5 rounded-lg border border-amber-300/80 bg-white text-stone-900 placeholder:text-stone-400 focus:outline-none focus:ring-2 focus:ring-amber-800/30 text-sm"
          />
          <div className="flex items-center justify-end gap-2 pt-1">
            <button
              type="button"
              onClick={() => setIsEditing(false)}
              className="px-3.5 py-1.5 rounded-lg text-xs font-medium text-stone-600 hover:text-stone-800"
            >
              Cancel
            </button>
            <button
              type="button"
              disabled={isSaving}
              onClick={handleSaveNotes}
              className="inline-flex items-center gap-1.5 px-4 py-1.5 rounded-lg bg-amber-900 hover:bg-amber-800 text-amber-50 text-xs font-semibold shadow-xs disabled:opacity-50"
            >
              {isSaving && <Loader2 className="w-3.5 h-3.5 animate-spin" />}
              <span>Save Notes</span>
            </button>
          </div>
        </div>
      )}

      {/* Display Notes Section */}
      <div className="bg-white rounded-2xl border border-stone-200/90 p-6 sm:p-8 shadow-xs">
        <h3 className="text-xs font-semibold uppercase tracking-wider text-stone-700 mb-4 pb-2 border-b border-stone-100 flex items-center justify-between">
          <span>Notes & Reflections</span>
          {book.notes && !isEditing && (
            <button
              onClick={() => {
                setEditedNotes(book.notes);
                setIsEditing(true);
              }}
              className="text-stone-700 hover:text-amber-900 text-xs flex items-center gap-1 font-normal lowercase"
            >
              <Edit3 className="w-3 h-3" /> edit
            </button>
          )}
        </h3>

        {book.notes ? (
          <div className="prose prose-stone max-w-none text-stone-800 text-base leading-relaxed whitespace-pre-line font-serif">
            {book.notes}
          </div>
        ) : (
          <div className="text-center py-8 text-stone-700">
            <p className="italic text-sm">No notes have been added yet.</p>
            <button
              onClick={() => setIsEditing(true)}
              className="mt-2 text-xs font-semibold text-amber-900 hover:underline inline-flex items-center gap-1"
            >
              <Edit3 className="w-3 h-3" /> Add personal notes
            </button>
          </div>
        )}
      </div>

      {/* Book Metadata footer */}
      <div className="bg-stone-50 rounded-xl p-4 border border-stone-200/60 text-xs text-stone-700 grid grid-cols-1 sm:grid-cols-2 gap-3">
        <div>
          <span className="font-semibold text-stone-700">Added to list:</span>{" "}
          {new Date(book.createdAt).toLocaleDateString(undefined, {
            year: "numeric",
            month: "long",
            day: "numeric",
          })}
        </div>
        {book.finishedAt && (
          <div>
            <span className="font-semibold text-stone-700">Finished on:</span>{" "}
            {new Date(book.finishedAt).toLocaleDateString(undefined, {
              year: "numeric",
              month: "long",
              day: "numeric",
            })}
          </div>
        )}
      </div>
    </div>
  );
}

import Link from "next/link";
import { notFound } from "next/navigation";
import { getBookById } from "@/lib/storage";
import BookDetailActions from "@/components/BookDetailActions";
import { ArrowLeft } from "lucide-react";
import type { Metadata } from "next";

export const dynamic = "force-dynamic";

interface Props {
  params: {
    id: string;
  };
}

export async function generateMetadata({ params }: Props): Promise<Metadata> {
  const book = await getBookById(params.id);
  if (!book) {
    return {
      title: "Book Not Found - Reading Log",
    };
  }

  return {
    title: `${book.title} by ${book.author} - Reading Log`,
    description: book.notes ? book.notes.slice(0, 160) : `Notes on ${book.title}`,
  };
}

export default async function BookDetailPage({ params }: Props) {
  const book = await getBookById(params.id);

  if (!book) {
    notFound();
  }

  const isReading = book.status === "reading";

  return (
    <div className="space-y-6 max-w-2xl mx-auto">
      {/* Back button */}
      <div>
        <Link
          href="/"
          className="inline-flex items-center gap-1.5 text-xs font-semibold text-stone-700 hover:text-stone-900 transition-colors py-1"
        >
          <ArrowLeft className="w-3.5 h-3.5" />
          <span>Back to Shelf</span>
        </Link>
      </div>

      {/* Book Header Card */}
      <div className="bg-white rounded-2xl border border-stone-200/90 p-6 sm:p-8 shadow-xs">
        <div className="flex items-center gap-2 mb-3">
          <span
            className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-semibold tracking-wide ${
              isReading
                ? "bg-amber-100 text-amber-900 border border-amber-200"
                : "bg-emerald-100 text-emerald-900 border border-emerald-200"
            }`}
          >
            <span
              className={`w-2 h-2 rounded-full ${
                isReading ? "bg-amber-600 animate-pulse" : "bg-emerald-600"
              }`}
            />
            {isReading ? "Currently Reading" : "Finished"}
          </span>
        </div>

        <h1 className="font-serif text-3xl sm:text-4xl font-bold tracking-tight text-stone-900 leading-tight">
          {book.title}
        </h1>
        <p className="font-medium text-stone-700 text-lg mt-1.5">
          by {book.author}
        </p>
      </div>

      {/* Interactive Actions, Notes & Sharing */}
      <BookDetailActions initialBook={book} />
    </div>
  );
}

