import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));

/** @type {import('next').NextConfig} */
const nextConfig = {
  reactStrictMode: true,
  webpack: (config) => {
    config.resolve.alias["@"] = path.resolve(__dirname, "src");
    return config;
  },
};

export default nextConfig;

import { describe, it, expect, beforeEach } from "vitest";
import fs from "node:fs/promises";
import path from "node:path";
import {
  getBooks,
  getBookById,
  createBook,
  updateBook,
  markBookAsFinished,
  deleteBook,
} from "../src/lib/storage";

describe("Book Storage Layer", () => {
  const dataFile = path.join(process.cwd(), "data", "books.json");

  it("should retrieve list of books", async () => {
    const books = await getBooks();
    expect(Array.isArray(books)).toBe(true);
    expect(books.length).toBeGreaterThan(0);
  });

  it("should add a new book to the library and persist to JSON file", async () => {
    const newBook = await createBook({
      title: "Clean Code",
      author: "Robert C. Martin",
      status: "reading",
      notes: "A handbook of agile software craftsmanship.",
    });

    expect(newBook.id).toBeDefined();
    expect(newBook.title).toBe("Clean Code");
    expect(newBook.author).toBe("Robert C. Martin");
    expect(newBook.status).toBe("reading");
    expect(newBook.notes).toBe("A handbook of agile software craftsmanship.");

    // Verify it is in storage
    const fetched = await getBookById(newBook.id);
    expect(fetched).not.toBeNull();
    expect(fetched?.title).toBe("Clean Code");

    // Verify raw JSON file directly on disk
    const fileContent = await fs.readFile(dataFile, "utf-8");
    const parsed = JSON.parse(fileContent);
    const inDisk = parsed.find((b: any) => b.id === newBook.id);
    expect(inDisk).toBeDefined();
    expect(inDisk.author).toBe("Robert C. Martin");
  });

  it("should mark a book as finished and record finishedAt timestamp", async () => {
    const testBook = await createBook({
      title: "Refactoring",
      author: "Martin Fowler",
      status: "reading",
      notes: "Improving the design of existing code.",
    });

    const finished = await markBookAsFinished(testBook.id);
    expect(finished?.status).toBe("finished");
    expect(finished?.finishedAt).toBeDefined();
    expect(typeof finished?.finishedAt).toBe("string");

    // Verify updated status in JSON file
    const fileContent = await fs.readFile(dataFile, "utf-8");
    const parsed = JSON.parse(fileContent);
    const inDisk = parsed.find((b: any) => b.id === testBook.id);
    expect(inDisk.status).toBe("finished");
    expect(inDisk.finishedAt).not.toBeNull();
  });

  it("should update notes for a book", async () => {
    const testBook = await createBook({
      title: "The Pragmatic Programmer",
      author: "David Thomas, Andrew Hunt",
      status: "reading",
      notes: "Initial note",
    });

    const updated = await updateBook(testBook.id, {
      notes: "Updated reflections: Care about your craft.",
    });

    expect(updated?.notes).toBe("Updated reflections: Care about your craft.");

    const fetched = await getBookById(testBook.id);
    expect(fetched?.notes).toBe("Updated reflections: Care about your craft.");
  });

  it("should delete a book if requested", async () => {
    const testBook = await createBook({
      title: "Temporary Book",
      author: "Test Author",
    });

    const deleted = await deleteBook(testBook.id);
    expect(deleted).toBe(true);

    const fetched = await getBookById(testBook.id);
    expect(fetched).toBeNull();
  });
});

